class Solution {
    struct TrieNode {
        TrieNode* children[26] = {};
        string word = "";
    };
    int m, n;
    vector<string> res;

    void dfs(vector<vector<char>>& board, int r, int c, TrieNode* curr) {
        char ch = board[r][c];
        int idx = ch - 'a';
        if (!curr->children[idx]) return;
        curr = curr->children[idx];
        if (!curr->word.empty()) {
            res.push_back(curr->word);
            curr->word = "";
        }

        board[r][c] = '#';
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (auto& d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] != '#') {
                dfs(board, nr, nc, curr);
            }
        }
        board[r][c] = ch;
    }
