class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word = null;
    }
    private int m, n;
    private List<String> res = new ArrayList<>();

    public List<String> findWords(char[][] board, String[] words) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode curr = root;
            for (char c : w.toCharArray()) {
                int idx = c - 'a';
                if (curr.children[idx] == null) curr.children[idx] = new TrieNode();
                curr = curr.children[idx];
            }
            curr.word = w;
        }

        m = board.length;
        n = board[0].length;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                dfs(board, r, c, root);
            }
        }
        return res;
    }

    private void dfs(char[][] board, int r, int c, TrieNode curr) {
        char ch = board[r][c];
        int idx = ch - 'a';
        if (curr.children[idx] == null) return;
        curr = curr.children[idx];
        if (curr.word != null) {
            res.add(curr.word);
            curr.word = null;
        }

        board[r][c] = '#';
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] != '#') {
                dfs(board, nr, nc, curr);
            }
        }
        board[r][c] = ch;
    }
}

var findWords = function(board, words) {
    const root = {};
    for (const w of words) {
        let curr = root;
        for (const ch of w) {
            if (!curr[ch]) curr[ch] = {};
            curr = curr[ch];
        }
        curr['$'] = w;
    }

    const m = board.length, n = board[0].length;
    const res = [];

    function dfs(r, c, curr) {
        const ch = board[r][c];
        if (!curr[ch]) return;
        curr = curr[ch];
        if (curr['$']) {
            res.push(curr['$']);
            delete curr['$'];
        }

        board[r][c] = '#';
        const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] !== '#') {
                dfs(nr, nc, curr);
            }
        }
        board[r][c] = ch;
    }

    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            dfs(r, c, root);
        }
    }
    return res;
};
